/* Small, reusable street props placed against the existing OSM building edges. */
window.createStreetAtmosphere=function(T,scene,city,sun,sign){
 const root=new T.Group();scene.add(root);const bins=new Map(),dummy=new T.Object3D();
 function cube(w,h,d,color,x,y,z,angle=0){const key=color;let list=bins.get(key);if(!list)bins.set(key,list=[]);list.push({w,h,d,x,y,z,angle});}
 const asphalt=document.createElement('canvas');asphalt.width=asphalt.height=128;const ctx=asphalt.getContext('2d');ctx.fillStyle='#555b60';ctx.fillRect(0,0,128,128);for(let i=0;i<2300;i++){ctx.fillStyle=i%2?'#73787b':'#444b50';ctx.fillRect(Math.random()*128,Math.random()*128,1,1)}
 const tex=new T.CanvasTexture(asphalt);tex.wrapS=tex.wrapT=T.RepeatWrapping;tex.colorSpace=T.SRGBColorSpace;
 const pos=city.streetMesh.geometry.attributes.position,uv=[];for(let i=0;i<pos.count;i++)uv.push(pos.getX(i)/5,pos.getZ(i)/5);city.streetMesh.geometry.setAttribute('uv',new T.Float32BufferAttribute(uv,2));city.streetMesh.material.map=tex;city.streetMesh.material.color.set('#ffffff');city.streetMesh.material.needsUpdate=true;city.buildings.material.color.set('#bcbab1');
 const anchors=city.liveDistrict?[]:city.venues.map(v=>v.approach),near=(x,z,r=110)=>anchors.some(p=>Math.hypot(x-p.x,z-p.z)<r);
 const shopNames=['早安早餐','阿嬤雜貨店','青菜水果','巷口茶飲','古早味小吃'];let shops=0;
 for(const s of city.segments){const dx=s.b.x-s.a.x,dz=s.b.z-s.a.z,len=Math.hypot(dx,dz),mx=(s.a.x+s.b.x)/2,mz=(s.a.z+s.b.z)/2;if(!near(mx,mz)||len<3||['footway','path','pedestrian','cycleway','corridor'].includes(s.kind))continue;
  const angle=Math.atan2(dx,dz),major=['primary','secondary','tertiary'].includes(s.kind),half=major?6:3.5,nx=dz/len,nz=-dx/len;
  if(major)for(const o of [-.12,.12])cube(.09,.012,len,'#e6b64e',mx+nx*o,.045,mz+nz*o,angle);
  for(const side of [-1,1]){cube(.14,.014,len*.82,'#b66058',mx+nx*(half-.12)*side,.05,mz+nz*(half-.12)*side,angle);for(let t=3;t<len-3;t+=18){const x=s.a.x+dx*t/len+nx*(half-.45)*side,z=s.a.z+dz*t/len+nz*(half-.45)*side;cube(.45,.015,.85,'#303b3b',x,.052,z,angle);for(let q=-.3;q<=.3;q+=.15)cube(.48,.02,.035,'#8b9391',x+dx*q/len,.066,z+dz*q/len,angle)}}
  if(major&&len>18)for(let k=-4;k<=4;k++)cube(.65,.014,2.8,'#eeeada',s.a.x+dx*3/len+nx*k*.85,.058,s.a.z+dz*3/len+nz*k*.85,angle+Math.PI/2);
 }
 // Illustrative shop rows fill gaps in the source's building coverage near entrances.
 const fronts=[],walls=[];if(!city.curated&&!city.liveDistrict)for(const v of city.venues){const q=city.closest(v.approach),s=q.s,dx=s.b.x-s.a.x,dz=s.b.z-s.a.z,len=Math.hypot(dx,dz),ux=dx/len,uz=dz/len,nx=uz,nz=-ux,half=['primary','secondary','tertiary'].includes(s.kind)?6:3.5;
  for(let t=4;t<len-3;t+=8)for(const side of [-1,1]){const x=s.a.x+ux*t+nx*(half+2)*side,z=s.a.z+uz*t+nz*(half+2)*side;if(Math.hypot(x-v.approach.x,z-v.approach.z)>42||city.blocked(x,z))continue;
   const angle=Math.atan2(ux,uz);cube(7,11,5,'#c2bbac',x+nx*2.5*side,5.5,z+nz*2.5*side,angle+Math.PI/2);fronts.push({points:[{x:x-ux*3.5,z:z-uz*3.5},{x:x+ux*3.5,z:z+uz*3.5}]});walls.push({x:x+nx*2.5*side,z:z+nz*2.5*side,ux,uz,w:3.5,d:2.5});
  }}
 const originalBlocked=city.blocked;city.blocked=(x,z)=>originalBlocked(x,z)||walls.some(w=>Math.abs((x-w.x)*w.ux+(z-w.z)*w.uz)<w.w&&Math.abs((x-w.x)*w.uz-(z-w.z)*w.ux)<w.d);
 // Facades follow existing polygon edges; props stay clear of the road center.
 for(const f of [...fronts,...city.footprints]){if(shops>95)break;for(let i=1;i<f.points.length;i++){const a=f.points[i-1],b=f.points[i],dx=b.x-a.x,dz=b.z-a.z,len=Math.hypot(dx,dz),mx=(a.x+b.x)/2,mz=(a.z+b.z)/2;if(len<5||len>90||!near(mx,mz,80))continue;const road=city.closest({x:mx,z:mz});if(!road||road.d>20||road.d<4)continue;const nx=(road.x-mx)/road.d,nz=(road.z-mz)/road.d,angle=Math.atan2(dx,dz),w=Math.min(12,len-.5),c=['#b87760','#698b80','#717d96','#b69761'][shops%4];
   cube(w,.18,1.8,c,mx+nx*.35,3.05,mz+nz*.35,angle+Math.PI/2);for(const t of [-w/2+.3,w/2-.3])cube(.2,3,.2,'#bdb8a8',mx+dx/len*t+nx*.9,1.5,mz+dz/len*t+nz*.9);
   cube(w,.08,1.7,'#c6c1b4',mx+nx*.3,.09,mz+nz*.3,angle+Math.PI/2);
   for(let floor=0;floor<3;floor++)for(let k=-w/2+1;k<w/2;k+=2.4){const x=mx+dx/len*k+nx*.08,z=mz+dz/len*k+nz*.08;cube(1.25,1.15,.12,'#627d87',x,4.3+floor*2.6,z,angle+Math.PI/2);cube(1.4,.09,.25,'#e2dbca',x,3.7+floor*2.6,z,angle+Math.PI/2);if(k<0)cube(.7,.4,.45,'#ddd9cc',x+nx*.3,3.45+floor*2.6,z+nz*.3,angle+Math.PI/2)}
   if(shops%3===0){const board=sign(shopNames[shops%shopNames.length],mx+nx*.55,2.6,mz+nz*.55,Math.min(w,5),root);board.rotation.y=Math.atan2(nx,nz);}
   // Parked scooters: two black wheels, body, saddle, steering stem.
   if(shops%2===0){const x=mx+nx*1.1,z=mz+nz*1.1,heading=angle+.3;for(const t of [-.55,.55])cube(.24,.48,.4,'#303638',x+Math.sin(heading)*t,.28,z+Math.cos(heading)*t,heading);cube(.48,.48,1.1,c,x,.55,z,heading);cube(.45,.12,.65,'#343b3c',x,.84,z,heading);cube(.12,.65,.12,'#bcc7c7',x+Math.sin(heading)*.55,.9,z+Math.cos(heading)*.55,heading);cube(.7,.08,.1,'#354044',x+Math.sin(heading)*.55,1.2,z+Math.cos(heading)*.55,heading);cube(.32,.26,.1,'#f0e4b8',x+Math.sin(heading)*.7,.85,z+Math.cos(heading)*.7,heading)}
   cube(.45,.45,.45,'#9a6e55',mx+nx*.9+dx/len*(w/2-.8),.3,mz+nz*.9+dz/len*(w/2-.8));cube(.7,.8,.6,'#6b9258',mx+nx*.9+dx/len*(w/2-.8),.85,mz+nz*.9+dz/len*(w/2-.8));shops++;break;
  }}
 for(const [color,list]of bins){const m=new T.InstancedMesh(new T.BoxGeometry(1,1,1),new T.MeshStandardMaterial({color,roughness:.85}),list.length);list.forEach((p,i)=>{dummy.position.set(p.x,p.y,p.z);dummy.rotation.set(0,p.angle,0);dummy.scale.set(p.w,p.h,p.d);dummy.updateMatrix();m.setMatrixAt(i,dummy.matrix)});m.receiveShadow=true;root.add(m)}
 const sky=new T.Mesh(new T.SphereGeometry(125,24,16),new T.ShaderMaterial({side:T.BackSide,depthWrite:false,uniforms:{top:{value:new T.Color('#73b9e5')},bottom:{value:new T.Color('#e8eee0')}},vertexShader:'varying vec3 v; void main(){v=position;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',fragmentShader:'varying vec3 v;uniform vec3 top;uniform vec3 bottom;void main(){gl_FragColor=vec4(mix(bottom,top,smoothstep(-.1,.7,normalize(v).y)),1.);}'}));sky.renderOrder=-1;root.add(sky);
 const clouds=new T.Group();root.add(clouds);const cloudMat=new T.MeshBasicMaterial({color:'#ffffff',transparent:true,opacity:.8,depthWrite:false});for(let i=0;i<14;i++)for(let j=0;j<3;j++){const m=new T.Mesh(new T.SphereGeometry(1,10,6),cloudMat);m.position.set(Math.sin(i*2.4)*65+j*3,28+i%4*3,Math.cos(i*2.4)*65);m.scale.set(6,1.7,3.5);clouds.add(m)}
 const rainPos=new Float32Array(450*6);const rainGeo=new T.BufferGeometry();rainGeo.setAttribute('position',new T.BufferAttribute(rainPos,3));const rain=new T.LineSegments(rainGeo,new T.LineBasicMaterial({color:'#d4e3ec',transparent:true,opacity:.45}));rain.frustumCulled=false;root.add(rain);
 const states=[{name:'☀ 藍天散步',top:'#73b9e5',fog:'#dce5df',sun:2.6},{name:'☁ 多雲微風',top:'#99aebd',fog:'#c8d2d1',sun:1.1},{name:'☂ 午後陣雨',top:'#657b8e',fog:'#a3b3bd',sun:.55}];let state=0,elapsed=0;
 const button=document.createElement('button');button.id='weather';button.style.cssText='position:absolute;right:16px;top:113px;z-index:5;border:0;border-radius:18px;padding:8px 10px;background:#ffffffe8;color:#31533e;font:11px system-ui';button.setAttribute('aria-label','切換天氣');document.getElementById('phone').appendChild(button);
 function setWeather(index){state=((index%3)+3)%3;elapsed=0;const s=states[state];sky.material.uniforms.top.value.set(s.top);sky.material.uniforms.bottom.value.set(s.fog);scene.fog.color.set(s.fog);scene.fog.near=35;scene.fog.far=115;sun.intensity=s.sun;cloudMat.color.set(state===2?'#adbac4':'#ffffff');rain.visible=state===2;city.streetMesh.material.roughness=state===2?.28:1;city.streetMesh.material.metalness=state===2?.15:0;button.textContent=s.name;}
 button.onclick=()=>setWeather(state+1);setWeather(Math.floor(Math.random()*3));
 return {setWeather,update(dt,p,inside){button.hidden=inside;if(inside){root.visible=false;scene.background.set('#dce8d3');sun.intensity=2.6;return}root.visible=true;sun.intensity=states[state].sun;elapsed+=dt;if(elapsed>150)setWeather(state+1);sky.position.copy(p);clouds.position.set(p.x,0,p.z);clouds.rotation.y+=dt*.003;rain.position.copy(p);if(state===2){for(let i=0;i<450;i++){const k=i*6;if(!rainPos[k+1]||rainPos[k+1]<0){rainPos[k]=(Math.random()-.5)*32;rainPos[k+1]=8+Math.random()*15;rainPos[k+2]=(Math.random()-.5)*32;}rainPos[k+1]-=dt*12;rainPos[k+3]=rainPos[k]-.1;rainPos[k+4]=rainPos[k+1]+.65;rainPos[k+5]=rainPos[k+2];}rainGeo.attributes.position.needsUpdate=true;}}};
};
